const usagesData1 = `-- name: UsagesData1 :many
SELECT payload FROM accelerator.usages WHERE tenant_id=$1 AND ($2='' OR owner_service=$2) AND ($3=0 OR revision=$3) AND resource_id>COALESCE(NULLIF($4,'')::uuid,'00000000-0000-0000-0000-000000000000') ORDER BY resource_id LIMIT $5
`

func (q *Queries) UsagesData1(ctx context.Context, tenantID string, column2 interface{}, column3 interface{}, column4 interface{}, limit int32) ([][]byte, error) {
	rows, err := q.db.Query(ctx, usagesData1,
		tenantID,
		column2,
		column3,
		column4,
		limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := [][]byte{}
	for rows.Next() {
		var payload []byte
		if err := rows.Scan(&payload); err != nil {
			return nil, err
		}
		items = append(items, payload)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
